import{_ as t,o as a,c as i,aw as r}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"Паттерны","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/theory/approaches/architecture/patterns.md","filePath":"wiki/dev-commit/theory/approaches/architecture/patterns.md"}'),o={name:"wiki/dev-commit/theory/approaches/architecture/patterns.md"};function l(n,e,s,c,p,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="паттерны" tabindex="-1">Паттерны <a class="header-anchor" href="#паттерны" aria-label="Permalink to &quot;Паттерны&quot;">​</a></h1><h2 id="паттерны-1" tabindex="-1">Паттерны <a class="header-anchor" href="#паттерны-1" aria-label="Permalink to &quot;Паттерны&quot;">​</a></h2><h3 id="composition-root-dependency-injection" tabindex="-1">Composition Root + Dependency Injection <a class="header-anchor" href="#composition-root-dependency-injection" aria-label="Permalink to &quot;Composition Root + Dependency Injection&quot;">​</a></h3><ul><li>Все зависимости создаются централизованно в одном модуле.</li><li>Фичи получают зависимости через DI (конструктор, контекст, провайдер).</li><li>Прямые импорты инфраструктуры из глубины feature-модулей запрещены.</li></ul><p>Эффект:</p><ul><li>управляемая инициализация;</li><li>предсказуемые замены в тестах;</li><li>проще мигрировать инфраструктуру.</li></ul><h3 id="repository-pattern" tabindex="-1">Repository Pattern <a class="header-anchor" href="#repository-pattern" aria-label="Permalink to &quot;Repository Pattern&quot;">​</a></h3><ul><li>Repository скрывает детали API/transport/cache.</li><li>Снаружи доступен только контракт: query, mutation, invalidate, refresh.</li><li>Domain-store не знает о протоколах, endpoint-ах и transport-ошибках.</li></ul><p>Эффект:</p><ul><li>бизнес-логика не привязана к источнику данных;</li><li>единая точка работы с кешем и синхронизацией.</li></ul><h3 id="store-pattern-feature-state-model" tabindex="-1">Store Pattern (Feature State Model) <a class="header-anchor" href="#store-pattern-feature-state-model" aria-label="Permalink to &quot;Store Pattern (Feature State Model)&quot;">​</a></h3><p>В каждом домене есть state-модель, которая хранит:</p><ul><li>текущее состояние;</li><li>derived-состояние;</li><li>операции пользователя;</li><li>статусы загрузки/ошибок.</li></ul><p>Правило:</p><ul><li>store управляет поведением фичи;</li><li>view только отображает и вызывает методы store/workflow.</li></ul><h3 id="workflow-pattern-use-case-orchestration" tabindex="-1">Workflow Pattern (Use Case Orchestration) <a class="header-anchor" href="#workflow-pattern-use-case-orchestration" aria-label="Permalink to &quot;Workflow Pattern (Use Case Orchestration)&quot;">​</a></h3><p>Workflow нужен, когда сценарий:</p><ul><li>затрагивает несколько repository/store;</li><li>требует post-action invalidate/refetch;</li><li>содержит redirect/post-submit/диалоги/уведомления;</li><li>объединяет cross-domain побочные эффекты.</li></ul><p>Workflow не нужен, когда операция тривиальна и просто проксирует один вызов.</p><h3 id="effect-pattern-reactive-side-effects" tabindex="-1">Effect Pattern (Reactive Side Effects) <a class="header-anchor" href="#effect-pattern-reactive-side-effects" aria-label="Permalink to &quot;Effect Pattern (Reactive Side Effects)&quot;">​</a></h3><ul><li>Побочные эффекты оформляются как отдельные эффекты, а не «размазываются» по UI.</li><li>Каждый effect имеет четкий trigger, guard-условия и cleanup.</li><li>Эффекты управляют внешними интеграциями (storage, browser APIs, notification channels, dialogs).</li></ul><h3 id="thin-route-pattern" tabindex="-1">Thin Route Pattern <a class="header-anchor" href="#thin-route-pattern" aria-label="Permalink to &quot;Thin Route Pattern&quot;">​</a></h3><ul><li>Route задает вход в экран и route-level guards.</li><li>Route не содержит domain-логики.</li><li>Route делегирует реализацию в view-модуль.</li></ul><h3 id="host-adapter-pattern-for-wiring" tabindex="-1">Host/Adapter Pattern for Wiring <a class="header-anchor" href="#host-adapter-pattern-for-wiring" aria-label="Permalink to &quot;Host/Adapter Pattern for Wiring&quot;">​</a></h3><p>Для сложных store полезно иметь host-адаптер, который:</p><ul><li>собирает dependencies;</li><li>создает store;</li><li>отдает готовый экземпляр в UI.</li></ul><p>Эффект:</p><ul><li>легче тестировать интеграцию;</li><li>проще переиспользовать wiring в разных местах.</li></ul>',28)])])}const f=t(o,[["render",l]]);export{u as __pageData,f as default};
